def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the contiguous non-background line that forms the stamp.
    stamps = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start >= 2:
                stamps.append((c-start, 'h', r, start,
                               [grid[r][j] for j in range(start, c)]))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start >= 2:
                stamps.append((r-start, 'v', start, c,
                               [grid[j][c] for j in range(start, r)]))

    if not stamps:
        return [row[:] for row in grid]
    _, orient, sr, sc, stamp = max(stamps, key=lambda x: x[0])
    out = [row[:] for row in grid]
    anchor = len(stamp) // 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for i, value in enumerate(stamp):
                    rr, cc = ((r, c + i - anchor) if orient == 'h'
                              else (r + i - anchor, c))
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
